from fai.consts import START_CODON_OFFSET
from fai.contracts import Read
from fai.logic import calculate_delta


def test_calculate_delta():
    gene_dict = {
        "gene1": "",  # noqa: E501
        "gene2": "",  # noqa: E501
        "gene3": "",  # noqa: E501
    }

    read_size = 30
    reads_spacing = 3
    expected_delta = 15
    minimum_read_starting_position = START_CODON_OFFSET - expected_delta - 1

    reads = [
        Read(
            gene,
            START_CODON_OFFSET - (expected_delta - 1) + offset * reads_spacing,
            read_size,
        )
        for gene in gene_dict
        for offset in range(
            0,
            (
                len(gene_dict[gene])
                - minimum_read_starting_position  # minimum read starting position
                - read_size
            )
            // reads_spacing
            + 1,  # include last possible read
        )
    ]

    delta = calculate_delta(reads, gene_dict)

    assert delta == expected_delta

    expected_delta = 14
    minimum_read_starting_position = START_CODON_OFFSET - expected_delta - 1

    reads = [
        Read(
            gene,
            START_CODON_OFFSET - (expected_delta - 1) + offset * reads_spacing,
            read_size,
        )
        for gene in gene_dict
        for offset in range(
            0,
            (len(gene_dict[gene]) - minimum_read_starting_position - read_size)
            // reads_spacing
            + 1,  # include last possible read
        )
    ]

    delta = calculate_delta(reads, gene_dict)

    assert delta == expected_delta

    expected_delta = 16
    minimum_read_starting_position = START_CODON_OFFSET - expected_delta - 1

    reads = [
        Read(
            gene,
            START_CODON_OFFSET - (expected_delta - 1) + offset * reads_spacing,
            read_size,
        )
        for gene in gene_dict
        for offset in range(
            0,
            (len(gene_dict[gene]) - minimum_read_starting_position - read_size)
            // reads_spacing
            + 1,  # include last possible read
        )
    ]

    delta = calculate_delta(reads, gene_dict)

    assert delta == expected_delta


def test_calculate_delta_with_unmatching_size_reads():
    gene_dict = {
        "gene1": "",  # noqa: E501
    }

    reads = [Read("gene1", 20, 25), Read("gene1", 50, 30), Read("gene1", 80, 35)]

    try:
        calculate_delta(reads, gene_dict)
    except ValueError as e:
        assert str(e) == "All reads must have the same size."
    else:
        assert False, "Expected ValueError was not raised."
